# DK KVD.  Kolding Syd - Vamdrup Øst
#
let kv = path("d3.dk.kvd");

with detail = 4, railway = :first :pax :removed {
    # point.dk.Kolding-Syd  dk.KHM

    with link = "line.dk.KVD" {
        track(:lor, kv[:kos + 0.49sw, :kos.yv] >> 1mo);
        track(:lor, kv[:kos.yv - 0.1dl, :kos.xv] >> 1mo);
        line_label(:right:n, kv[:kos.xv] >> 1mo >> 0.5mt, "KVD");
        track(
                kv[:kos.xv - 0.1dl, :kos.xv] >> 1mo
            ..  kv[:kos.xv + 600m, :kos.zv + 1.81km]
        );
        track(kv[:kos.zv + 1.79km, :von - 0.49sw]);
    }

    with link = "point.dk.Vonsild", railway = :station {
        track(kv[:von - 0.5sw, :von + 0.5sw]);
        marker(:right :de.bf, kv[:von] >> 0.5mt);
        station(:left, kv[:von] >> 0.5mt >> 1sh + (-1.8dt, 1.3dt),
            "Vonsild", "KVD: 6,4"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:von + 0.49sw, :hop - 0.49sw]);
    }

    with link = "point.dk.Hoppeshuse", railway = :station {
        track(kv[:hop - 0.5sw, :hop + 0.5sw]);
        marker(:right :de.bf, kv[:hop] >> 0.5mt);
        station(:left, kv[:hop] >> 0.5mt >> 1sh + (-1.9dt, 0.2dt),
            "Hoppeshuse", "KVD: 9,9"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:hop + 0.49sw, :fov - 0.49sw]);
    }

    with link = "point.dk.Fovslet", railway = :station {
        track(kv[:fov - 0.5sw, :fov + 0.5sw]);
        marker(:left :de.bf, kv[:fov] << 0.5mt);
        station(:right, kv[:fov] << 0.5mt << 1sh + (1.8dt, 0.9dt),
            "Fovslet", "KVD: 12,0"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:fov + 0.49sw, :tap - 0.49sw]);
    }

    with link = "point.dk.Taps", railway = :station {
        track(kv[:tap - 0.5sw, :tap + 0.5sw]);
        marker(:left :de.bf, kv[:tap] << 0.5mt);
        station(:right:left_align,
            kv[:tap] << 0.5mt << 1sh + (1.8dt, 1.5dt),
            "Taps", " KVD: 15,4"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:tap + 0.49sw, :tao - 0.49sw]);
    }

    with link = "point.dk.Tapsøre", railway = :station {
        track(kv[:tao - 0.5sw, :tao + 0.5sw]);
        marker(:left :de.hp, kv[:tao] << 0.5mt);
        station(:bottom, kv[:tao] << 0.5mt << 1sh + (-0.8dt, 1dt),
            span(:former, "Tapsore"),
            "Tapsøre",
            "KVD: 17,1"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:tap + 0.49sw, :bra - 0.49sw]);
    }

    with link = "point.dk.Brænore", railway = :station {
        track(kv[:bra - 0.5sw, :bra + 0.5sw]);
        marker(:right :de.hp, kv[:bra] >> 0.5mt);
        station(:left, kv[:bra] << 0.5mt + (-2dt, 1.2dt),
            "Brænore", "KVD: 19,3"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:bra + 0.49sw, :odi - 0.49sw]);
    }

    with link = "point.dk.Ødis", railway = :station {
        track(kv[:odi - 0.5sw, :odi + 0.5sw]);
        marker(:right :de.bf, kv[:odi] >> 0.5mt);
        station(:top, kv[:odi] >> 0.5mt >> 1sh >> 0.8dt,
            "Ødis", "KVD: 22,2"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:odi + 0.49sw, :obr - 0.49sw]);
    }

    with link = "point.dk.Ødis-Bramdrup", railway = :station {
        track(kv[:obr - 0.5sw, :obr + 0.5sw]);
        marker(:left :de.bf, kv[:obr] << 0.5mt);
        station(:bottom, kv[:obr] << 0.5mt << 1sh << 0.8dt,
            "Ødis-Bramdrup", "KVD: 24,7"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:obr + 0.49sw, :gas - 0.49sw]);
    }

    with link = "point.dk.Gåskær", railway = :station {
        track(kv[:gas - 0.5sw, :gas + 0.5sw]);
        marker(:right :de.bf, kv[:gas] >> 0.5mt);
        station(:left, kv[:gas] << 0.5mt + (-2.3dt, 1.0dt),
            "Gåskær", "KVD: 26,4"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:gas + 0.49sw, :ova - 0.49sw]);
    }

    with link = "point.dk.Øster-Vamdrup", railway = :station {
        track(kv[:ova - 0.5sw, :ova + 0.5sw]);
        marker(:left :de.hp, kv[:ova] << 0.5mt);
        station(:bottom, kv[:ova] << 0.5mt << 1sh + (-5.5dt, 1.0dt),
            "Øster Vamdrup", "KVD: 29,4"
        );
    }

    with link = "line.dk.KVD" {
        track(kv[:ova + 0.49sw, :vao - 0.49sw]);
    }

    with link = "point.dk.Vamdrup-Øst", railway = :station {
        track(kv[:vao - 0.5sw, :vao.f]);
        marker(:left :de.bf, kv[:vao] << 0.5mt);
        station(:right, kv[:vao] >> 0.5mt + (2.5dt, -0.8dt),
            span(:bold, "Vamdrup Øst"), "KVD: 30,4"
        );
    }
}

